package owl.nh;
import java.util.*;
import net.unethicalite.api.widgets.Tab;

/** Entry crossing and simultaneous-danger regressions, without game inputs. */
public final class OlmOverlapTests {
 static void check(boolean ok,String text){CoreTests.check(ok,"Olm overlap: "+text);}
 static OlmSpecials.Cell c(int x,int y){return new OlmSpecials.Cell(x,y,0);}
 public static void main(String[] args){
  OlmMechanicAdapter.Config effects=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.hazardEffectNpc(effects,123,"Lightning")&&OlmMechanicAdapter.hazardEffectNpc(effects,123,"Crystal bomb")&&!OlmMechanicAdapter.hazardEffectNpc(effects,7555,"Great Olm's clenched claw"),"lightning effect NPCs are handled as tile hazards, while physical boss NPCs still block movement");
  OlmElectricForecast trailing=new OlmElectricForecast();OlmSpecials.View before=electric(c(0,0),c(0,1),c(3,0),c(3,1));before.player=c(0,5);trailing.forecast(before,0);OlmSpecials.View after=electric(c(0,1),c(0,2),c(3,1),c(3,2));after.player=c(0,5);after.tick=10;trailing.forecast(after,30);check(!after.uncertainElectric.contains(c(1,1))&&!after.uncertainElectric.contains(c(1,2)),"trailing lightning inherits its observed lane direction instead of inventing lateral barriers");after.hazards.add(new OlmSpecials.Hazard(after.player,OlmSpecials.HazardKind.FALLING,2));after.reachable.add(c(1,5));after.reachable.add(c(-1,5));after.rangeLocked=true;after.attackTiles.add(c(1,5));OlmSpecials.Choice overlapEscape=new OlmSpecials().choose(after);check(overlapEscape.kind==OlmSpecials.Kind.MOVE&&!overlapEscape.cell.equals(after.player)&&OlmSpecials.escapeStep(after,after.player,overlapEscape.cell),"overlapping crystal buffer and incoming lightning lane still permit a perpendicular escape");
  OlmSpecials.View uncertain=OlmSpecialsTests.view();uncertain.uncertainElectric.add(uncertain.player);check(new OlmSpecials().choose(uncertain).kind==OlmSpecials.Kind.MOVE,"new uncertain lightning near the player triggers avoidance before its motion is known");

  OlmElectricForecast timed=new OlmElectricForecast();timed.forecast(electric(c(0,0)),0);OlmSpecials.View dps=electric(c(0,1));dps.electricLookaheadCycles=60;dps.player=c(0,6);timed.forecast(dps,30);check(dps.hazards.stream().noneMatch(h->h.contains(dps.player)),"measured distant lightning leaves a melee DPS window before the dodge deadline");check(dps.hazards.stream().anyMatch(h->h.contains(c(0,3))),"two-tick movement margin is still reserved ahead of the wall");OlmSpecials.View due=electric(c(0,4));due.electricLookaheadCycles=60;due.player=c(0,6);due.reachable.add(c(1,6));timed.forecast(due,120);check(due.hazards.stream().anyMatch(h->h.contains(due.player))&&new OlmSpecials().choose(due).kind==OlmSpecials.Kind.MOVE,"approaching wall ends DPS and forces the dodge before arrival");OlmSpecials.View stale=electric(c(0,4));stale.electricLookaheadCycles=60;stale.player=c(0,12);timed.forecast(stale,200);check(stale.hazards.stream().anyMatch(h->h.contains(stale.player)),"stale melee timing falls back to reserving the full known trajectory");
  crossingAndRestore();
  stationaryMage();
  check(OlmEntryFlow.crossedFromOutside(c(1,0),c(0,0),c(-3,0))&&!OlmEntryFlow.crossedFromOutside(c(-1,0),c(0,0),c(-3,0)),"gate crossing latches before any boss NPC has spawned");check(OlmEntryFlow.crossedFromOutside(c(0,-1),c(0,0),c(0,3)),"boss-free crossing works from the opposite gate side");
  electricMotion();actorCrystals();lanesAndRepeatedCrystals();
  check(!OlmEntryFlow.pastGate(c(0,-1),c(0,0),c(0,12))&&OlmEntryFlow.pastGate(c(0,1),c(0,0),c(0,12)),"gate crossing works without recorded fight bounds");
  check(OlmEntryFlow.pastGate(c(-1,0),c(0,0),c(-12,0))&&!OlmEntryFlow.pastGate(c(1,0),c(0,0),c(-12,0)),"mirrored gate direction follows the boss side");
  check(!OlmEntryFlow.pastGate(c(0,1),c(0,0),new OlmSpecials.Cell(0,12,1)),"different planes do not invent a crossing");
  for(int stage=0;stage<3;stage++){OlmEntryFlow flow=new OlmEntryFlow();flow.sentGate(1);if(stage>=1)flow.sentBegin(2);if(stage==2){flow.next(3,true,false,false,false,false);flow.next(38,true,false,false,false,false);flow.sentGate(39);}check(flow.insideEvidence(false,true),"crossing accepted in either gate/dialogue stage");flow.confirmInside();check(flow.next(10000,true,true,true,true,false)==OlmEntryFlow.Action.WAIT&&flow.stage()==OlmEntryFlow.Stage.INSIDE,"confirmed entry never reclicks a visible gate");}
  OlmEntryFlow inside=new OlmEntryFlow();inside.sentGate(1);inside.confirmInside();check(inside.insideDialogueDue(2),"chat can finish after crossing without reopening entry");inside.sentContinue(2);check(!inside.insideDialogueDue(3)&&inside.insideDialogueDue(17)&&inside.next(100,true,false,false,false,false)==OlmEntryFlow.Action.WAIT,"continuation preserves the inside latch and is not spammed");
  OlmSpecials policy=new OlmSpecials();OlmSpecials.View v=OlmSpecialsTests.view();v.oneTileFalling=true;v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.FALLING,2));v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.CRYSTAL_BOMB,4));
  OlmSpecials.Choice choice=policy.choose(v);check(choice.kind==OlmSpecials.Kind.MOVE&&choice.cell.distance(v.player)==1&&choice.context.equals("COMBINED"),"overlapping crystal and bomb buffers escape together rather than deadlocking");OlmSpecials.Cell selected=choice.cell;Collections.reverse(v.hazards);check(policy.choose(v).cell.equals(selected),"hazard scan order cannot change the escape");
  v.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.ELECTRIC,0));choice=policy.choose(v);check(choice.kind==OlmSpecials.Kind.MOVE&&choice.cell.equals(c(0,1)),"combined dodge does not step into an electric wall");
  check(!OlmSpecials.escapeStep(v,c(0,0),c(1,0)),"reachability rejects a new electric danger even while fleeing another special");
  v=OlmSpecialsTests.view();v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.FALLING,2));check(OlmMechanicAdapter.pendingDodgeSafe(v,c(1,0)),"submitted outward dodge can coexist with supplies before leaving the entire crystal buffer");v.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.ELECTRIC,0));check(!OlmMechanicAdapter.pendingDodgeSafe(v,c(1,0)),"new electric wall invalidates a previously submitted dodge");
  v=OlmSpecialsTests.view();v.oneTileFalling=true;v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.FALLING,2));v.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.ELECTRIC,1));check(policy.choose(v).kind==OlmSpecials.Kind.MOVE,"already overlapping electric and falling danger permits outward progress from both");
  policy=new OlmSpecials();v=OlmSpecialsTests.view();for(int x=-1;x<=1;x++){v.walls.add(c(x,1));v.walls.add(c(x,-1));}v.reachable.clear();v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.CRYSTAL_BOMB,4));choice=policy.choose(v);check(choice.kind==OlmSpecials.Kind.BREAK_WALL,"bomb inside flame walls opens a gap when movement is blocked");v.walls.remove(choice.cell);v.reachable.add(choice.cell);v.tick++;check(policy.choose(v).kind==OlmSpecials.Kind.MOVE,"observed gap enables escape while bomb remains active");
  int[] cycle={100};VisibleCombatUi ui=new VisibleCombatUi(()->cycle[0],tab->true,tab->{});check(ui.ready(Tab.PRAYER,100)&&!ui.claim(),"defensive prayer owns its client-cycle action");cycle[0]++;check(ui.claim(),"next client cycle remains available for simultaneous hazard movement");
  cycle[0]=200;List<String> actions=new ArrayList<>();check(ui.claim(),"urgent dodge gets the first client-cycle slot");actions.add("dodge");check(!ui.ready(Tab.PRAYER,100),"prayer cannot replace an already issued dodge in the same client cycle");cycle[0]++;check(ui.ready(Tab.PRAYER,100),"next client cycle permits protection without waiting for a game tick");actions.add("prayer");cycle[0]++;check(ui.ready(Tab.INVENTORY),"inventory sip can follow dodge and prayer within the same game tick");actions.add("sip");check(actions.equals(Arrays.asList("dodge","prayer","sip")),"compatible actions preserve ordered single-cycle outputs");
  System.out.println("Olm overlap checks passed: gate-side entry latch, no gate after crossing, simultaneous crystal/bomb/electric escape, flame-gap recovery and prayer/movement action slots. Synthetic only.");
 }
 private static void stationaryMage(){
  OlmMechanicAdapter.Config config=new OlmMechanicAdapter.Config();OlmCrystalMarker marker=new OlmCrystalMarker();OlmSpecials policy=new OlmSpecials();
  for(int tick=335;tick<355;tick++){OlmSpecials.View v=electric(c(7428,14288));v.player=c(7424,14299);v.target=c(7432,14297);v.tick=tick;v.holdSafeTile=true;v.tickWalking=true;v.attackDue=false;v.reachable.add(c(7425,14298));v.hazards.add(new OlmSpecials.Hazard(c(7430,14295),OlmSpecials.HazardKind.FALLING,0));v.hazards.add(new OlmSpecials.Hazard(c(7432,14297),OlmSpecials.HazardKind.FALLING,0));marker.observe(OlmMechanicAdapter.actorFallingGraphic(config,2856),v.player,tick,true);marker.add(v,0);check(policy.choose(v).kind==OlmSpecials.Kind.NONE,"recorded mage pattern: repeated unverified actor event and distant specials preserve a safe camp");}
  OlmSpecials.View v=OlmSpecialsTests.view();v.holdSafeTile=true;v.reachable.add(c(2,0));v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.UNDERFOOT,0));v.attackTiles.add(c(1,0));v.attackTiles.add(c(2,0));OlmSpecials.Choice dodge=policy.choose(v);check(dodge.kind==OlmSpecials.Kind.MOVE&&dodge.cell.distance(v.player)==1,"real danger takes the shortest safe in-range escape");v.player=dodge.cell;check(policy.choose(v).kind==OlmSpecials.Kind.NONE,"after escaping hold the new safe camp rather than returning or improving position");v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));check(policy.choose(v).kind==OlmSpecials.Kind.MOVE,"stationary preference never suppresses a confirmed crystal at the new camp");
 }
 private static void crossingAndRestore(){
  OlmMechanicAdapter.Config crossingConfig=new OlmMechanicAdapter.Config();check(!OlmMechanicAdapter.crossingEnabled(crossingConfig),"existing run-through preference cannot enable unverified Orion crossing timing");crossingConfig.lightningCrossingTimingVerified=true;check(OlmMechanicAdapter.crossingEnabled(crossingConfig),"crossing requires explicit timing verification");crossingConfig.runAcrossLightning=false;check(!OlmMechanicAdapter.crossingEnabled(crossingConfig),"verification does not override disabled crossing preference");
  OlmElectricForecast forecast=new OlmElectricForecast();forecast.forecast(electric(c(0,0)),0);forecast.forecast(electric(c(0,1)),30);check(c(0,1).equals(forecast.crossingTarget(c(0,3),30)),"approaching wall exactly two tiles away supplies its actual occupied tile");check(forecast.crossingTarget(c(0,4),30)==null&&forecast.crossingTarget(c(0,0),30)==null,"no crossing trigger at the wrong distance or behind a receding wall");check(forecast.crossingTarget(c(0,3),60)==null,"a stale wall direction cannot trigger a run-through");
  OlmSpecials.View view=new OlmSpecials.View();view.player=c(0,3);List<int[]> actual=new ArrayList<>();actual.add(new int[]{0,1,0});check(OlmMechanicAdapter.crossingClear(view,actual,c(0,1)),"explicit two-tile run-through can target the lightning tile");view.hazards.add(new OlmSpecials.Hazard(c(0,2),OlmSpecials.HazardKind.FALLING,0));check(!OlmMechanicAdapter.crossingClear(view,actual,c(0,1)),"crystals on the crossing route force normal hazard handling");view.hazards.clear();actual.add(new int[]{0,2,0});check(!OlmMechanicAdapter.crossingClear(view,actual,c(0,1)),"second occupied lightning tile blocks the run-through");
  OlmMechanicAdapter.Config config=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.electricRadius(config)==0,"adjacent lightning tiles are not treated as occupied by the old safety halo");config.exactLightningTiles=false;check(OlmMechanicAdapter.electricRadius(config)==1,"legacy lightning padding remains explicitly configurable");
  OlmOverheadRestore restore=new OlmOverheadRestore();check(restore.desired(false,false,99,100)==null,"no invented overhead before observing one");restore.observed(net.runelite.api.Prayer.PROTECT_FROM_MAGIC);check(restore.desired(false,false,99,100)==net.runelite.api.Prayer.PROTECT_FROM_MAGIC,"knocked-off protection restores the last confirmed overhead");check(restore.desired(false,true,99,100)==null&&restore.desired(true,false,99,100)==null&&restore.desired(false,false,0,100)==null,"incoming hits, active overheads and empty prayer prevent duplicate restoration");restore.requested(100);check(restore.desired(false,false,99,101)==null&&restore.desired(false,false,99,130)!=null,"restoration waits for acknowledgement before a bounded retry");
 }
 private static void lanesAndRepeatedCrystals(){
  OlmElectricForecast growing=new OlmElectricForecast();growing.forecast(electric(c(0,0)),0);OlmSpecials.View growingView=electric(c(0,0),c(0,1));growing.forecast(growingView,30);check(growingView.hazards.stream().anyMatch(h->h.contains(c(0,10))),"new lightning front establishes trajectory while the old graphic is still visible");
  OlmSpecials.View ranged=OlmSpecialsTests.view();ranged.oneTileFalling=true;ranged.hazards.add(new OlmSpecials.Hazard(ranged.player,OlmSpecials.HazardKind.FALLING,2));ranged.attackTiles.add(c(0,1));ranged.attackDistance.put(c(0,1),8);ranged.attackDistance.put(c(1,0),11);check(new OlmSpecials().choose(ranged).cell.equals(c(0,1)),"partial crystal escape prefers retaining ranged DPS range over an equally safe off-range tile");
  OlmSpecials.View holding=OlmSpecialsTests.view();holding.holdSafeTile=true;holding.tickWalking=true;holding.attackDue=false;holding.hazards.add(new OlmSpecials.Hazard(c(8,8),OlmSpecials.HazardKind.FALLING,2));check(new OlmSpecials().choose(holding).kind==OlmSpecials.Kind.NONE,"safe mage camp stays still even during a distant crystal event and attack cooldown");holding.hazards.add(new OlmSpecials.Hazard(holding.player,OlmSpecials.HazardKind.FALLING,0));check(new OlmSpecials().choose(holding).kind==OlmSpecials.Kind.MOVE,"hold-safe mode retains urgent crystal escapes");
  OlmSpecials.View overlap=new OlmSpecials.View();overlap.player=c(4,12);overlap.oneTileFalling=true;overlap.hazards.add(new OlmSpecials.Hazard(overlap.player,OlmSpecials.HazardKind.FALLING,2));for(int y=8;y<=16;y++)overlap.hazards.add(new OlmSpecials.Hazard(c(4,y),OlmSpecials.HazardKind.ELECTRIC,1));overlap.reachable.add(c(5,12));check(OlmSpecials.escapeStep(overlap,c(4,12),c(5,12))&&!OlmMechanicAdapter.electricCrossing(overlap,c(4,12),c(5,12))&&new OlmSpecials().choose(overlap).kind==OlmSpecials.Kind.MOVE,"overlapping crystal and full electric lane permit a one-tile perpendicular escape rather than deadlocking on neighboring buffer circles");
  OlmElectricForecast forecast=new OlmElectricForecast();OlmSpecials.View v=electric(c(4,0),c(8,20));v.player=c(12,10);forecast.forecast(v,0);v=electric(c(4,1),c(8,19));v.player=c(12,10);forecast.forecast(v,30);check(v.hazards.stream().anyMatch(h->h.contains(c(4,12)))&&v.hazards.stream().anyMatch(h->h.contains(c(8,8))),"reserve full independent north/south sweeps well ahead of the player");check(v.hazards.stream().noneMatch(h->h.contains(c(12,10))),"rows outside electric trajectories remain usable");v.player=c(4,12);v.reachable.clear();v.reachable.add(c(5,12));check(new OlmSpecials().choose(v).kind==OlmSpecials.Kind.MOVE,"escape a reserved lane before a distant wall gets near");
  v=electric(c(1,0));v.needsApproach=true;v.target=c(2,0);v.attackTiles.add(c(1,0));v.attackTiles.add(c(0,1));OlmSpecials.Choice approach=new OlmSpecials().choose(v);check(approach.kind==OlmSpecials.Kind.MOVE&&approach.cell.equals(c(0,1)),"melee approach picks the safe attack row rather than the nearer electrified tile");v.attackTiles.remove(c(0,1));check(new OlmSpecials().choose(v).kind==OlmSpecials.Kind.HOLD,"do not chase a hand when every mapped melee row is unsafe");
  Set<OlmSpecials.Cell> perimeter=OlmSpecials.meleeTiles(c(1,0),3,4);check(perimeter.contains(c(0,2))&&!perimeter.contains(c(0,-1))&&!perimeter.contains(c(2,2)),"melee camps are adjacent to the real hand perimeter, excluding diagonal corners and occupied tiles");
  OlmMechanicAdapter.Config signals=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.installedFalling(signals,net.runelite.api.ProjectileID.OLM_FALLING_CRYSTAL_TRAIL),"1352 falling trail participates in the complete sequence");check(!OlmMechanicAdapter.actorFallingGraphic(signals,2856)&&OlmMechanicAdapter.fallingProjectile(signals,2857),"unverified persistent actor graphic cannot manufacture chasing crystal hazards");signals.orionActorCrystal2856Verified=true;check(OlmMechanicAdapter.actorFallingGraphic(signals,2856),"actor candidate requires independent explicit verification");signals.useOrionCrystalSignals=false;check(!OlmMechanicAdapter.actorFallingGraphic(signals,2856)&&!OlmMechanicAdapter.fallingProjectile(signals,2857),"Orion-specific candidates can be disabled independently of standard crystal mappings");
  OlmCrystalMarker marker=new OlmCrystalMarker();OlmSpecials policy=new OlmSpecials();OlmSpecials.Cell position=c(0,0);int opportunities=0;
  for(int shot=0;shot<6;shot++){int tick=200+shot*5;marker.observe(true,position,tick,true);int direction=position.y==0?1:-1;
   for(int step=0;step<3;step++){v=new OlmSpecials.View();v.player=position;v.tick=tick+step;v.attackDue=true;v.oneTileFalling=true;v.attackTiles.addAll(perimeter);v.reachable.add(c(0,position.y+direction));marker.observe(true,position,v.tick);marker.add(v,2);OlmSpecials.Choice dodge=policy.choose(v);check(dodge.kind==OlmSpecials.Kind.MOVE&&dodge.cell.distance(position)==1,"each repeated crystal escapes the complete buffer in adjacent steps");position=dodge.cell;}
   v=new OlmSpecials.View();v.player=position;v.tick=tick+2;v.attackDue=true;v.attackTiles.addAll(perimeter);marker.observe(true,position,v.tick);marker.add(v,2);check(policy.choose(v).kind==OlmSpecials.Kind.NONE&&v.attackTiles.contains(position),"persistent marker does not chase the player; safe melee DPS can resume between drops");opportunities++;
  }check(opportunities==6,"six successive marker events all leave an attack opportunity after dodging");
 }
 private static void actorCrystals(){
  net.runelite.api.events.ProjectileMoved event=new net.runelite.api.events.ProjectileMoved();event.setProjectile(ChambersTests.fake(net.runelite.api.Projectile.class,Collections.emptyMap()));net.runelite.api.coords.LocalPoint destination=new net.runelite.api.coords.LocalPoint(640,768);event.setPosition(destination);check(destination.equals(OlmMechanicAdapter.eventLanding(event)),"ground-target event remains usable when projectile target getter is null");Map<String,Object> projectileFields=new HashMap<>();projectileFields.put("getTarget",new net.runelite.api.coords.LocalPoint(128,128));event.setProjectile(ChambersTests.fake(net.runelite.api.Projectile.class,projectileFields));check(destination.equals(OlmMechanicAdapter.eventLanding(event)),"event destination takes precedence over a different target getter");event.setPosition(null);check(projectileFields.get("getTarget").equals(OlmMechanicAdapter.eventLanding(event)),"target getter is retained as fallback when event position is absent");
  OlmMechanicAdapter.Config geometry=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.fallingRadius(geometry,OlmStrategy.Phase.FINAL_HANDS)==2&&OlmMechanicAdapter.fallingRadius(geometry,OlmStrategy.Phase.HEAD)==2,"phase-three hands and head share the two-tile landing buffer");OlmSpecials.View finalView=OlmSpecialsTests.view();finalView.oneTileFalling=true;finalView.hazards.add(new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.FALLING,OlmMechanicAdapter.fallingRadius(geometry,OlmStrategy.Phase.FINAL_HANDS)));OlmSpecials policy=new OlmSpecials();for(int step=0;step<3;step++){finalView.reachable.clear();finalView.reachable.add(c(step+1,0));OlmSpecials.Choice dodge=policy.choose(finalView);check(dodge.kind==OlmSpecials.Kind.MOVE&&dodge.cell.distance(finalView.player)==1,"phase-three escape keeps making adjacent outward steps until outside the full buffer");finalView.player=dodge.cell;finalView.tick++;}check(policy.choose(finalView).kind==OlmSpecials.Kind.NONE,"escape finishes beyond the two-tile landing radius");
  OlmCrystalMarker marker=new OlmCrystalMarker();marker.observe(true,c(0,0),100);OlmSpecials.View v=OlmSpecialsTests.view();v.tick=100;v.oneTileFalling=true;marker.add(v,2);check(new OlmSpecials().choose(v).kind==OlmSpecials.Kind.MOVE,"actor crystal marker triggers a one-tile escape even without scene graphics/projectiles");
  marker.observe(true,c(1,0),100);v=OlmSpecialsTests.view();v.tick=100;v.player=c(1,0);marker.add(v,0);check(v.hazards.get(0).cell.equals(c(0,0)),"same-tick marker stays at its latched landing tile instead of chasing the dodge");
  marker.observe(true,c(1,0),101,true);marker.observe(false,c(1,0),102);v=OlmSpecialsTests.view();v.tick=102;marker.add(v,0);check(v.hazards.size()==1&&v.hazards.get(0).cell.equals(c(1,0)),"repeated markers rearm next tick and survive a briefly masking spot animation");v.hazards.clear();v.tick=104;marker.add(v,0);check(v.hazards.isEmpty(),"marker grace expires rather than walking forever");marker.reset();v.tick=101;marker.add(v,0);check(v.hazards.isEmpty(),"new run cannot inherit a previous crystal marker");
  java.util.Map<String,Object> fields=new java.util.HashMap<>();fields.put("getGraphic",net.runelite.api.GraphicID.OLM_FALLING_CRYSTAL_TRAIL);fields.put("getWorldLocation",new net.runelite.api.coords.WorldPoint(3200,3200,0));net.runelite.api.Player player=ChambersTests.fake(net.runelite.api.Player.class,fields);java.util.Map<String,Object> clientFields=new java.util.HashMap<>();clientFields.put("getLocalPlayer",player);clientFields.put("getTickCount",10);net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,clientFields);OlmMechanicAdapter adapter=new OlmMechanicAdapter(client);adapter.configure(new OlmFighter.Profile());adapter.actorGraphic(player);check(((java.util.List<?>)adapter.diagnostics().get("actorGraphics")).contains(net.runelite.api.GraphicID.OLM_FALLING_CRYSTAL_TRAIL),"production actor event records crystal signal for attempt diagnosis");
  clientFields.put("getBaseX",3200);clientFields.put("getBaseY",3200);OlmFighter.Profile profile=new OlmFighter.Profile();profile.provisionalTest=true;adapter.configure(profile);projectileFields.clear();projectileFields.put("getId",net.runelite.api.ProjectileID.OLM_FALLING_CRYSTAL);event.setProjectile(ChambersTests.fake(net.runelite.api.Projectile.class,projectileFields));event.setPosition(destination);adapter.projectile(event);check(((Number)adapter.diagnostics().get("activeFallingTargets")).intValue()==1,"production crystal adapter retains a ground event despite an empty target getter");
 }
 private static OlmSpecials.View electric(OlmSpecials.Cell... cells){OlmSpecials.View v=OlmSpecialsTests.view();for(OlmSpecials.Cell cell:cells)v.hazards.add(new OlmSpecials.Hazard(cell,OlmSpecials.HazardKind.ELECTRIC,0));return v;}
 private static void electricMotion(){
  OlmElectricForecast replay=new OlmElectricForecast();OlmSpecials.View fresh=electric(c(4,4));fresh.player=c(4,1);replay.forecast(fresh,0);check(fresh.uncertainElectric.contains(c(4,2))&&!OlmSpecials.escapeStep(fresh,c(4,1),c(4,2)),"recorded failure: do not approach a newly observed wall before its direction is known");check(OlmSpecials.escapeStep(fresh,c(4,1),c(3,2)),"uncertain trajectory still permits a clear adjacent row");fresh=electric(c(4,4),c(4,3));fresh.player=c(3,2);fresh.holdSafeTile=true;replay.forecast(fresh,30);check(fresh.hazards.stream().anyMatch(h->h.contains(c(4,2)))&&new OlmSpecials().choose(fresh).kind==OlmSpecials.Kind.NONE,"observed incoming lane is reserved while the safe adjacent camp stays stationary");
  OlmElectricForecast forecast=new OlmElectricForecast();Object entity=new Object();OlmSpecials.View v=electric(c(0,0));forecast.observe(entity,c(0,0),0);forecast.forecast(v,0);check(v.hazards.size()==1,"first electric sample cannot invent velocity");
  v=electric(c(0,1));forecast.observe(entity,c(0,1),30);forecast.forecast(v,30);check(v.hazards.stream().anyMatch(h->h.contains(c(0,2))),"observed northbound wall forecasts its next tile before arrival");v.player=c(0,2);check(new OlmSpecials().choose(v).kind==OlmSpecials.Kind.MOVE,"predicted wall intersection triggers an early dodge");
  forecast.clear();forecast.forecast(electric(c(0,0),c(2,0)),0);v=electric(c(0,1),c(2,1));forecast.forecast(v,30);check(v.hazards.stream().anyMatch(h->h.contains(c(2,2))),"recreated graphics preserve a uniquely observed wave translation");
  v=electric(c(0,1),c(2,1));forecast.forecast(v,100);check(v.hazards.size()==2,"stale wall velocity does not keep projecting a stationary wave");
  forecast.clear();forecast.forecast(electric(c(0,0),c(4,0)),0);v=electric(c(0,1),c(4,-1));forecast.forecast(v,30);check(v.hazards.stream().anyMatch(h->h.contains(c(0,8)))&&v.hazards.stream().anyMatch(h->h.contains(c(4,-8))),"opposing recreated waves retain independent sweep lanes");
  forecast.clear();forecast.observe(entity,c(0,0),0);forecast.forecast(electric(c(0,0)),0);forecast.observe(entity,c(2,1),30);v=electric(c(2,1));forecast.forecast(v,30);check(v.hazards.stream().anyMatch(h->h.contains(c(4,2))),"diagonal prediction preserves measured slope rather than forcing forty-five degrees");
  OlmSpecials policy=new OlmSpecials();for(int y=0;y<4;y++){v=electric(c(1,y));v.tickWalking=true;v.attackDue=false;check(policy.choose(v).kind==OlmSpecials.Kind.NONE,"safe camp does not follow a passing adjacent wall");v.needsApproach=true;v.target=c(5,0);check(policy.choose(v).kind==OlmSpecials.Kind.HOLD,"approach waits for electric walls instead of following alongside");}
  v=electric(c(1,0));v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.FALLING,0));check(policy.choose(v).kind==OlmSpecials.Kind.MOVE,"holding camp never disables an actual crystal escape");
 }
}
